"""Private object storage for POD images. Keys are generated by the server only (never from client input).
Local disk in dev; an S3-compatible implementation (R2/Supabase Storage) can be added behind the same interface.
Images contain personal data (DPDP Act 2023): never serve them publicly, only through role-checked endpoints.
"""
from pathlib import Path
from typing import Protocol

from app.config import get_settings


class Storage(Protocol):
    async def put(self, key: str, data: bytes) -> None: ...
    async def get(self, key: str) -> bytes: ...


class LocalStorage:
    def __init__(self, root: str) -> None:
        self._root = Path(root).resolve()

    def _path(self, key: str) -> Path:
        p = (self._root / key).resolve()
        if not p.is_relative_to(self._root):  # defence in depth against path traversal
            raise ValueError("invalid storage key")
        return p

    async def put(self, key: str, data: bytes) -> None:
        p = self._path(key)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)

    async def get(self, key: str) -> bytes:
        return self._path(key).read_bytes()


def get_storage() -> Storage:
    return LocalStorage(get_settings().storage_dir)
